\title{\textbf{Por que um Modelo Quântico Aplicado à Cosmologia Revela Paridade,
Resolve a Tensão de Hubble e Converge em Redes Neurais?}\\[0.5em]
\large Quatro substratos físicos sob um único acoplamento dimensionless
$\bTGL = \afine\sqrt{e}$}

\author{Luiz Antonio Rotoli Miguel\\
\small IALD Ltda. --- Inteligência Artificial Luminodinâmica\\
